/* Update function for moby class 1353 on level 13: runs the state machine in moby->state. */
void gemlik_scene_controller_update(Moby *moby) {
    MobyData *data = (MobyData *)moby->pvars;

    switch (moby->state) {
        case 0:
            if (gemlik_game_mode_r == 0)
                moby->state = 1;
            break;
        case 1:
            if (((Flags *)gSpecialItems)->f64 == 0) {
                ((Flags *)gSpecialItems)->f64 = 1;
                moby->state = 2;
                start_scene(0);
            } else {
                moby->state = 3;
            }
            break;
        case 2:
            if (gemlik_game_mode_r != 2)
                moby->state = 3;
            break;
        case 3:
            moby->state = 4;
            break;
        case 4:
            if (((Flags *)gSpecialItems)->f65 == 0) {
                if (data->f0 != -1) {
                    if (is_point_inside_clip_volume(&g_hero.motion.pos, data->f0) != 0) {
                        ((Flags *)gSpecialItems)->f65 = 1;
                        if (data->f14 != -1) {
                            Moby *e = &gemlik_moby_array_start_r[data->f14];
                            e->flags |= 0x41;
                        }
                        moby->state = 5;
                        start_scene(1);
                    }
                } else {
                    moby->state = 7;
                }
            } else {
                moby->state = 6;
            }
            if (moby->state != 4 && data->fC != -1) {
                DeleteMoby(&gemlik_moby_array_start_r[data->fC]);
            }
            break;
        case 5:
            if (gemlik_game_mode_r == 2)
                break;
            if (data->f14 != -1) {
                Moby *e = &gemlik_moby_array_start_r[data->f14];
                e->flags &= 0xFFBE;
            }
            if (data->f8 != -1 && data->f10 != -1) {
                Moby *e = &gemlik_moby_array_start_r[data->f10];
                qcopy_nc(&e->pos, gemlik_scene_points[data->f8].f30);
                set_race_camera(gemlik_scene_points[data->f8].f30, gemlik_scene_points[data->f8].f70, 0, 1);
                g_hero_field_20a5[0] = 1;
                ((MobyData *)e->pvars)->f7C = 0.99f;
                gemlik_fade_level = 0.99f;
                e->state = 2;
            }
            moby->state = 6;
            break;
        case 6:
            moby->state = 7;
            break;
        case 7:
            if (((Flags *)gSpecialItems)->f66 != 0)
                goto s12;
            if (data->f14 == -1)
                goto s13;
            {
                Moby *e = &gemlik_moby_array_start_r[data->f14];
                if (e != 0 && e->oclass == MOBY_CLASS_UNMARKED_COUNTED_TARGET && e->state != 0xFE && e->state != 0xFD)
                    break;
            }
            if (data->f10 != -1) {
                Moby *e = &gemlik_moby_array_start_r[data->f10];
                e->flags |= 2;
            }
            set_race_camera(gemlik_scene_points[data->f8].f30, gemlik_scene_points[data->f8].f70, 0x72, 1);
            ((Flags *)gSpecialItems)->f66 = 1;
            if (data->f20 != -1) {
                Moby *e = &gemlik_moby_array_start_r[data->f20];
                e->flags |= 0x41;
            }
            request_music_track(0, 5);
            moby->state = 8;
            start_scene(2);
            break;
        case 8:
            if (gemlik_game_mode_r != 2) {
                moby->state = 9;
                PlayMovieEntryIfIdle(0xE);
            }
            break;
        case 9:
            if (gemlik_game_mode_r != 2) {
                start_scene(3);
                moby->state = 10;
            }
            break;
        case 10:
            if (gemlik_game_mode_r == 2)
                break;
            if (data->f10 != -1) {
                Moby *e = &gemlik_moby_array_start_r[data->f10];
                e->flags &= 0xFFFD;
            }
            unlock_planet(0xE);
            if (data->f20 != -1) {
                Moby *e = &gemlik_moby_array_start_r[data->f20];
                e->flags &= 0xFFBE;
                initialize_moby_state_record(e);
                ((Cam *)level_render_state)->f60 = 464.66f;
                ((Cam *)level_render_state)->f64 = 580.68f;
                ((Cam *)level_render_state)->f68 = 316.72f;
                ((Cam *)level_render_state)->f78 = 2.77f;
            }
            gemlik_scripted_camera_active = 0;
            moby->state = 11;
            break;
        case 11:
            if (data->f10 == -1)
                goto s12;
            {
                Moby *e = &gemlik_moby_array_start_r[data->f10];
                if (e != 0 && e->oclass == MOBY_CLASS_FIGHTER_JET_69 && e->state != 0xFE && e->state != 0xFD)
                    break;
            }
            memcard_Save(0, -1);
            moby->state = 12;
            break;
        s12:
            moby->state = 12;
            break;
        case 12:
        s13:
            moby->state = 13;
            break;
        case 13:
            if (data->f10 != -1) {
                if (gemlik_mission_group_state[gemlik_moby_array_start_r[data->f10].mission] != 0xFF)
                    break;
                if (data->f20 != -1) {
                    DeleteMoby(&gemlik_moby_array_start_r[data->f20]);
                }
                moby->state = 14;
            } else {
                DeleteMoby(moby);
            }
            break;
        case 14:
            moby->flags |= 2;
            break;
    }
}

