/* Follows its target moby along a path: snaps to the nearest path point, then walks the path segments. */
void moby_path_follower_update(char *m) {
    int *d = ((int *)((Moby *)m)->pvars);
    char *path;
    char *pth;
    char *o;
    float v[4];
    int idx;
    float t;
    int i;
    if (((unsigned char *)m)[0x20] == 0) {
        ((unsigned char *)m)[0x30] = 0xFF;
        if (d[1] != -1) {
            path = walker_paths[d[1]];
            for (i = 0; i < *(int *)path; i++) {
                *(float *)(path + (i << 4) + 0x1C) =
                    fast_vec_dist(path + (i * 16 + 0x10), path + ((i + 1) % *(int *)path * 16 + 0x10));
            }
        }
        d[2] = 0;
        d[3] = 0;
        m[0x20] = 1;
        d[4] = 0;
    }
    if (d[0] == -1)
        return;
    o = (char *)(gemlik_moby_array_start_m + (d[0] << 8));
    if (o == 0 || ((unsigned char *)o)[0x20] == 0xFE || ((unsigned char *)o)[0x20] == 0xFD) {
        DeleteMoby(m);
        return;
    }
    if (((unsigned char *)o)[0x20] >= 7) {
        d[4]++;
        if (d[1] == -1)
            return;
        pth = walker_paths[d[1]];
        if (((unsigned char *)m)[0x20] == 1) {
            find_nearest_path_point(pth, o + 0x10, v, &idx, &t, 0, 100.0f, 1.0f, 0.0f);
            if (idx > d[2] || t > ((float *)d)[3] || d[4] < 0x1E) {
                d[2] = idx;
                ((float *)d)[3] = t;
                qcopy(m + 0x10, v);
            } else {
                m[0x20] = 2;
            }
        }
        if (((unsigned char *)m)[0x20] == 2) {
            if (d[2] < *(int *)pth - 1) {
                int k = compute_advanced_moby_path_position(m, pth, m + 0x10, d[2], 1, frame_scale * 0.25f);
                d[2] = k;
                ((float *)d)[3] = fast_vec_dist(m + 0x10, pth + (k * 16 + 0x10));
            } else {
                m[0x20] = 3;
            }
        }
    } else {
        qcopy(m + 0x10, o + 0x10);
    }
}
