/* Records the classes of the tracked mobys, then removes this moby once too few of them are left.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l13/gameplay/vendor/003058a8.c, FUN_L13_0030be60. */
void tracked_group_watcher_update(struct Moby *m) {
    int *d = (int *)m->pvars;
    if (m->state == 0) {
        int *ids = d + 4;
        int *cls = d + 12;
        char *base;
        int i;
        m->state = 1;
        base = (char *)moby_base;
        for (i = 0; i < 8; i++) {
            unsigned char *o = (unsigned char *)(base + (ids[i] << 8));
            if (o != 0 && o[0x20] != 0xFE && o[0x20] != 0xFD)
                cls[i] = *(short *)(o + 0xA6);
            else
                cls[i] = -1;
        }
        if (d[0] == 0)
            m->state = 2;
    } else if (m->state == 1) {
        int *ids = d + 4;
        int *cls = d + 12;
        char *base = (char *)moby_base;
        int n = 0;
        int i;
        for (i = 0; i < 8; i++) {
            int id = ids[i];
            int c;
            unsigned char *o;
            if (id != -1 && (c = cls[i]) != -1) {
                o = (unsigned char *)(base + (id << 8));
                if (o != 0 && *(short *)(o + 0xA6) == c && o[0x20] != 0xFE && o[0x20] != 0xFD) {
                    n++;
                    continue;
                }
            }
            cls[i] = -1;
        }
        if (n < d[0])
            DeleteMoby(m);
    }
}

/* Spawns a class 0x660 moby at position, scaled and owned by owner. */
char *spawn_hit_proxy(char *owner, void *position, float scale) {
    char *moby = CreateMoby(0x660);
    if (moby != 0) {
        char *data = ((char *)((Moby *)moby)->pvars);
        ((struct Moby *)moby)->update_dist = 0xFF;
        ((Moby *)moby)->draw_dist = 0xFF;
        ((struct Moby *)moby)->visible = 1;
        ((struct Moby *)moby)->state = 0;
        ((struct HitProxyVars *)data)->owner = owner;
        ((Moby *)moby)->scale = *(float *)(*(char **)&((struct Moby *)moby)->pclass + 0x24) * scale;
        qcopy(&((struct Moby *)moby)->pos, position);
        if (owner != 0) {
            ((struct HitProxyVars *)data)->owner_id = *(short *)(owner + 0xA6);
        }
        *(char **)(data) = (char *)((struct HitProxyVars *)data)->hit_data;
        ((Moby *)moby)->flags |= 0x20;
        moby_build_matrix(moby);
    }
    return moby;
}

/* updates the moby: deletes it when its owner is gone, else copies the owner's effect data and marks it */
void hit_proxy_update(char *moby) {
    struct HitProxyVars *data = (struct HitProxyVars *)((Moby *)moby)->pvars;
    char *owner = data->owner;
    char *p;
    char buf[0x30];
    if (owner == 0 || *(short *)(owner + 0xA6) != data->owner_id || (unsigned char)owner[0x20] == 0xFE ||
        (unsigned char)owner[0x20] == 0xFD) {
        DeleteMoby(moby);
        return;
    }
    p = MobyGetHitMessage(moby, -1, 0);
    if (p != 0) {
        qcopy(buf, &((struct HitMessage *)p)->unk_10);
        *(int *)(buf + 0x10) = *(int *)&((struct HitMessage *)p)->source;
        *(int *)(buf + 0x14) = ((struct HitMessage *)p)->flags;
        buf[0x18] = *(char *)&((struct HitMessage *)p)->unk_28;
        buf[0x19] = p[0x29];
        *(short *)(buf + 0x1A) = ((struct HitMessage *)p)->unk_2A;
        *(float *)(buf + 0x1C) = ((struct HitMessage *)p)->damage;
        *(int *)(buf + 0x20) = ((struct HitMessage *)p)->unk_30;
        record_moby_hit(*(void **)&data->owner, buf);
    }
    ((unsigned char *)moby)[0xA4] = 0xFF;
}

